const STORAGE_KEY = "kioskDataSettings"; window.addEventListener("DOMContentLoaded", () => { setDefaultTodayDate(); loadSettings(); toggleOptionalFields(); toggleLivePanel(); toggleQRVisibility(); setupDragAndDrop(); setupPasteSupport(); liveUpdate(); }); function setDefaultTodayDate() { const today = new Date(); const yyyy = today.getFullYear(); const mm = String(today.getMonth() + 1).padStart(2, '0'); const dd = String(today.getDate()).padStart(2, '0'); document.getElementById('openingDate').value = `${yyyy}-${mm}-${dd}`; } function formatDateToDDMMYYYY(dateString) { if (!dateString) return ""; const parts = dateString.split("-"); if (parts.length === 3) { return `${parts[2]}-${parts[1]}-${parts[0]}`; } return dateString; } function toggleLivePanel() { const showLive = document.getElementById('toggleLivePreview').checked; const previewSec = document.getElementById('previewSection'); const formSec = document.getElementById('formSection'); const appContainer = document.getElementById('appContainer'); const btnGenSubmit = document.getElementById('btnGenerateSubmit'); if (showLive) { previewSec.style.display = 'flex'; formSec.style.display = 'block'; appContainer.classList.remove('preview-hidden', 'form-hidden'); btnGenSubmit.style.display = 'none'; } else { previewSec.style.display = 'none'; formSec.style.display = 'block'; appContainer.classList.add('preview-hidden'); appContainer.classList.remove('form-hidden'); btnGenSubmit.style.display = 'block'; } } function handleFormGenerate(event) { event.preventDefault(); if (!validateForm()) return; liveUpdate(); const showLive = document.getElementById('toggleLivePreview').checked; if (!showLive) { document.getElementById('formSection').style.display = 'none'; document.getElementById('previewSection').style.display = 'flex'; document.getElementById('appContainer').classList.remove('preview-hidden'); document.getElementById('appContainer').classList.add('form-hidden'); } } function showFormBack() { const showLive = document.getElementById('toggleLivePreview').checked; const formSec = document.getElementById('formSection'); const previewSec = document.getElementById('previewSection'); const appContainer = document.getElementById('appContainer'); formSec.style.display = 'block'; if (!showLive) { previewSec.style.display = 'none'; appContainer.classList.add('preview-hidden'); appContainer.classList.remove('form-hidden'); } else { previewSec.style.display = 'flex'; appContainer.classList.remove('preview-hidden', 'form-hidden'); } } function liveUpdate() { const getVal = (id) => document.getElementById(id).value || ""; const rawDate = getVal('openingDate'); const formattedDate = formatDateToDDMMYYYY(rawDate); document.getElementById('outOpeningDate').textContent = formattedDate; document.getElementById('outCifNumber').textContent = getVal('CifNumber'); document.getElementById('outAccount').textContent = getVal('account'); document.getElementById('fpbifscOut').textContent = getVal('ifsc'); const custName = getVal('Customer'); document.getElementById('outCustomer').textContent = custName; document.title = custName ? `${custName} - Identity Card` : "Identity Card Generator"; document.getElementById('outPerent').textContent = getVal('Perent'); document.getElementById('outMobile').textContent = getVal('mobile'); document.getElementById('outAadhar').textContent = getVal('aadhar'); document.getElementById('outAddress').textContent = getVal('Address'); document.getElementById('outPincode').textContent = getVal('Pincode'); document.getElementById('fpbkoNameOut').textContent = getVal('KoName'); document.getElementById('fpblocationOut').textContent = getVal('Location'); updateQRCode(custName, getVal('account'), getVal('ifsc'), formattedDate); } function updateQRCode(name, acc, ifsc, date) { let qrText = `Name: ${name || 'N/A'}\nAcc: ${acc || 'N/A'}\nIFSC: ${ifsc || 'N/A'}`; const showOpeningDate = document.getElementById('toggleOpeningDate').checked; if (showOpeningDate && date) { qrText += `\nDate: ${date}`; } const encodedText = encodeURIComponent(qrText); document.getElementById('previewQR').src = `https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=${encodedText}`; } function formatAadhar(input) { let val = input.value.replace(/\D/g, ''); val = val.substring(0, 12); let formatted = ''; for (let i = 0; i < val.length; i++) { if (i > 0 && i % 4 === 0) formatted += ' '; formatted += val[i]; } input.value = formatted; } function validateForm() { const acc = document.getElementById('account').value.trim(); const confirmAcc = document.getElementById('confirm_account').value.trim(); const mobile = document.getElementById('mobile').value.trim(); const pincode = document.getElementById('Pincode').value.trim(); const mobileEnabled = document.getElementById('toggleMobile').checked; if (acc !== confirmAcc) { alert("Account Number and Confirm Account Number do not match!"); return false; } if (mobileEnabled && mobile && !/^\d{10}$/.test(mobile)) { alert("Mobile Number must be exactly 10 digits!"); return false; } if (pincode && !/^\d{6}$/.test(pincode)) { alert("Pin Code must be exactly 6 digits!"); return false; } return true; } function processImageFile(file) { if (!file || !file.type.startsWith('image/')) { alert("Please select a valid image file."); return; } const reader = new FileReader(); reader.onload = function(e) { document.getElementById('previewPhoto').src = e.target.result; }; reader.readAsDataURL(file); } function handleFileSelect(event) { const file = event.target.files[0]; if (file) processImageFile(file); } function setupDragAndDrop() { const overlay = document.getElementById('dropOverlay'); let dragCounter = 0; window.addEventListener('dragenter', (e) => { e.preventDefault(); dragCounter++; overlay.classList.add('active'); }); window.addEventListener('dragleave', (e) => { e.preventDefault(); dragCounter--; if (dragCounter === 0) { overlay.classList.remove('active'); } }); window.addEventListener('dragover', (e) => { e.preventDefault(); }); window.addEventListener('drop', (e) => { e.preventDefault(); dragCounter = 0; overlay.classList.remove('active'); if (e.dataTransfer.files && e.dataTransfer.files.length > 0) { processImageFile(e.dataTransfer.files[0]); } }); } function setupPasteSupport() { window.addEventListener('paste', (e) => { const items = (e.clipboardData || e.originalEvent.clipboardData).items; for (let item of items) { if (item.kind === 'file' && item.type.startsWith('image/')) { const blob = item.getAsFile(); processImageFile(blob); break; } } }); } function toggleOptionalFields() { const showOpeningDate = document.getElementById('toggleOpeningDate').checked; const showAadhar = document.getElementById('toggleAadhar').checked; const showMobile = document.getElementById('toggleMobile').checked; document.getElementById('groupOpeningDate').style.display = showOpeningDate ? 'flex' : 'none'; document.getElementById('groupAadhar').style.display = showAadhar ? 'flex' : 'none'; document.getElementById('groupMobile').style.display = showMobile ? 'flex' : 'none'; document.getElementById('rowOpeningDate').style.display = showOpeningDate ? 'table-row' : 'none'; document.getElementById('rowAadhar').style.display = showAadhar ? 'table-row' : 'none'; document.getElementById('rowMobile').style.display = showMobile ? 'table-row' : 'none'; liveUpdate(); } function toggleQRVisibility() { const isVisible = document.getElementById('qrToggle').checked; document.getElementById('qrCardContainer').style.display = isVisible ? 'flex' : 'none'; } function downloadJPG() { if (!validateForm()) return; const card = document.getElementById('passbookCard'); const custName = document.getElementById('Customer').value.trim(); const fileName = custName ? `${custName}.jpg` : 'Identity Card.jpg'; html2canvas(card, { scale: 3, useCORS: true, logging: false, backgroundColor: "#ffffff" }).then(canvas => { const imageURI = canvas.toDataURL("image/jpeg", 0.95); const link = document.createElement("a"); link.download = fileName; link.href = imageURI; document.body.appendChild(link); link.click(); document.body.removeChild(link); }).catch(err => { console.error("Download Error:", err); alert("Failed to render identity card image."); }); } function openPDFBlob() { if (!validateForm()) return; const card = document.getElementById('passbookCard'); html2canvas(card, { scale: 3, useCORS: true, logging: false, backgroundColor: "#ffffff" }).then(canvas => { const imgData = canvas.toDataURL('image/jpeg', 0.95); const { jsPDF } = window.jspdf; const pdf = new jsPDF('p', 'mm', 'a4'); const imgProps = pdf.getImageProperties(imgData); const pdfWidth = 120; const pdfHeight = (imgProps.height * pdfWidth) / imgProps.width; pdf.addImage(imgData, 'JPEG', 15, 15, pdfWidth, pdfHeight); const blob = pdf.output('bloburl'); window.open(blob, '_blank'); }).catch(err => { console.error("PDF Generation Error:", err); alert("Failed to generate PDF."); }); } function triggerPrint() { if (!validateForm()) return; window.print(); } function resetForm() { document.getElementById('resumeForm').reset(); setDefaultTodayDate(); document.getElementById('previewPhoto').src = "data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='90' height='110' viewBox='0 0 90 110'><rect width='100%' height='100%' fill='%23eee'/><text x='50%' y='50%' dominant-baseline='middle' text-anchor='middle' font-family='sans-serif' font-size='12' fill='%23aaa'>No Photo</text></svg>"; localStorage.removeItem(STORAGE_KEY); document.getElementById('qrToggle').checked = true; document.getElementById('toggleLivePreview').checked = true; document.getElementById('toggleOpeningDate').checked = true; document.getElementById('toggleAadhar').checked = true; document.getElementById('toggleMobile').checked = true; toggleLivePanel(); toggleQRVisibility(); toggleOptionalFields(); liveUpdate(); } function autoSaveSettings() { const data = { ifsc: document.getElementById("ifsc").value, KoName: document.getElementById("KoName").value, Location: document.getElementById("Location").value, qrStatus: document.getElementById("qrToggle").checked, livePreviewStatus: document.getElementById("toggleLivePreview").checked, optOpeningDate: document.getElementById("toggleOpeningDate").checked, optAadhar: document.getElementById("toggleAadhar").checked, optMobile: document.getElementById("toggleMobile").checked }; localStorage.setItem(STORAGE_KEY, JSON.stringify(data)); } function loadSettings() { const saved = localStorage.getItem(STORAGE_KEY); if (!saved) return; try { const data = JSON.parse(saved); if (data.ifsc !== undefined) document.getElementById("ifsc").value = data.ifsc; if (data.KoName !== undefined) document.getElementById("KoName").value = data.KoName; if (data.Location !== undefined) document.getElementById("Location").value = data.Location; if (data.qrStatus !== undefined) document.getElementById("qrToggle").checked = data.qrStatus; if (data.livePreviewStatus !== undefined) document.getElementById("toggleLivePreview").checked = data.livePreviewStatus; if (data.optOpeningDate !== undefined) document.getElementById("toggleOpeningDate").checked = data.optOpeningDate; if (data.optAadhar !== undefined) document.getElementById("toggleAadhar").checked = data.optAadhar; if (data.optMobile !== undefined) document.getElementById("toggleMobile").checked = data.optMobile; } catch (e) { console.error("Could not parse saved settings", e); } }